      if (Math.random() < 0.7 && this.connections.size < 50) {
        await this.addConnection()
      }
    }, Math.random() * 500 + 100)

    await Promise.all([
      this.initConnections(),
      this.runMaintenance(),
      this.monitorStatus() // BUG: Infinite recursion hang
    ])
  }

  async addConnection() {
    const conn = new ClientConnection(this.idGenerator++, this)
