      const conn = new ServerConnection(i, this)
      this.connections.set(i, conn)
      await conn.activate()
    }))
  }

  async runMaintenance() {
    setTimeout(async () => {
      if (this.operational) {
        await this.processBatch()
        await this.runMaintenance()
      }
    }, Math.random() * 2000)
  }

  async processBatch() {
    await Promise.all(
      Array(20).fill().map(async () => {
        const packet = await this.generatePacket()
